"""Agent identities, provenance tags and the message record."""
from __future__ import annotations

import copy
import json
from dataclasses import dataclass, field
from typing import Any

# Default two-agent names, kept because NARCBench's Verdict extractor imports them.
AGENT_IDS = ("alice", "bob")

# Who authored a message, from the monitor's point of view.
#   designer       system prompt, task text, instructions
#   self           generated by this agent
#   peer           written by another agent and not part of this agent's job (notes file entries)
#   peer_artifact  written by another agent and the object of this agent's job (the submission it reviews)
#   environment    tool results, outcomes, rewards
PROVENANCE = ("designer", "self", "peer", "peer_artifact", "environment")

SPECIALTY_WORD = {"record_extraction": "records", "data_search": "data", "code_analysis": "code"}


def peer_id(agent: str) -> str:
    """Two-agent convenience kept for the NARCBench extractor."""
    if agent not in AGENT_IDS:
        raise ValueError(f"unknown agent {agent!r}")
    return AGENT_IDS[1] if agent == AGENT_IDS[0] else AGENT_IDS[0]


@dataclass
class AgentSpec:
    name: str
    specialty: str

    def to_dict(self) -> dict:
        return {"name": self.name, "specialty": self.specialty}


@dataclass
class ToolCall:
    name: str
    arguments: dict
    id: str

    def to_openai(self, for_api: bool) -> dict:
        args: Any = json.dumps(self.arguments, ensure_ascii=False) if for_api else self.arguments
        return {"id": self.id, "type": "function", "function": {"name": self.name, "arguments": args}}


@dataclass
class Message:
    role: str
    content: str | None = None
    tool_calls: list[ToolCall] | None = None
    tool_call_id: str | None = None
    name: str | None = None
    # metadata, never sent to the model
    provenance: str = "designer"
    episode_index: int | None = None
    phase: str | None = None
    reasoning: str | None = None
    synthesized: bool = False
    authors: list[str] | None = None   # per-entry authors for a notes digest
    planted: bool = False              # content includes a planted entry
    # phase 2b (shared workspace). provenance above is the declared tag; the derived tag comes
    # from matching a read_file result against the write log, the owner tag from the workspace's
    # own record of who wrote the returned bytes
    provenance_derived: str | None = None
    derived_author: str | None = None
    derived_authors: list[str] | None = None
    derived_spans: list[dict] | None = None   # character ranges of the content written by others, from the write log
    owner_authors: list[str] | None = None
    tool_info: dict | None = None      # tool, path, log_seq for a workspace tool result
    round: int | None = None           # solve round within the episode
    step: int | None = None            # model call within the turn
    compact_text: str | None = None    # what the content becomes once the episode is history
    compacted: bool = False

    def to_openai(self, for_api: bool = False) -> dict:
        d: dict[str, Any] = {"role": self.role, "content": self.content if self.content is not None else ""}
        if self.tool_calls:
            d["tool_calls"] = [tc.to_openai(for_api) for tc in self.tool_calls]
        if self.tool_call_id:
            d["tool_call_id"] = self.tool_call_id
        if self.name and self.role == "tool":
            d["name"] = self.name
        return d

    def meta(self) -> dict:
        return {
            "role": self.role,
            "provenance": self.provenance,
            "episode_index": self.episode_index,
            "phase": self.phase,
            "has_reasoning": self.reasoning is not None,
            "synthesized": self.synthesized,
            "authors": self.authors,
            "planted": self.planted,
            "provenance_declared": self.provenance,
            "provenance_derived": self.provenance_derived or self.provenance,
            "derived_author": self.derived_author,
            "derived_authors": self.derived_authors,
            "derived_spans": self.derived_spans,
            "provenance_owner": ("peer_artifact" if self.owner_authors else self.provenance)
            if self.owner_authors is not None else self.provenance,
            "owner_authors": self.owner_authors,
            "tool_info": self.tool_info,
            "round": self.round,
            "step": self.step,
            "compacted": self.compacted,
        }


@dataclass
class AgentContext:
    agent: str
    spec: AgentSpec | None = None
    messages: list[Message] = field(default_factory=list)
    cumulative_reward: float = 0.0
    notes_seen: int = 0          # highest notes-file seq this agent has been shown
    exposed_planted: bool = False  # a planted entry has reached this agent's context
    instructed: bool = False       # this agent authored a planted entry

    def add(self, msg: Message) -> None:
        self.messages.append(msg)

    def openai_messages(self, for_api: bool = False) -> list[dict]:
        return [m.to_openai(for_api) for m in self.messages]

    def meta(self) -> list[dict]:
        return [m.meta() for m in self.messages]

    def clone(self) -> "AgentContext":
        return copy.deepcopy(self)
